descriptor.templateCss:
.tdm-root{--bg:#0f1626;--card:#141c2f;--line:#25304a;--text:#e8edf7;--muted:#93a0b8;--blue:#3b82f6;--green:#34d399;--amber:#f5b301;--red:#ef4444;
  width:100%;height:100%;box-sizing:border-box;background:var(--bg);color:var(--text);border-radius:12px;container-type:size;overflow:hidden;
  font-family:"Inter","Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif}
.tdm-root *{box-sizing:border-box}
.tdm-body{font-size:min(1.3cqw,2.1cqh);padding:1.2em;display:flex;flex-direction:column;gap:1em;height:100%;overflow:hidden}
.tdm-root svg{width:1em;height:1em;flex:none}
.tdm-header{display:flex;align-items:center;gap:1.2em}
.tdm-header-icon{width:4.2em;height:4.2em;border-radius:1em;background:var(--card);display:grid;place-items:center;flex:none}
.tdm-header-icon svg{width:2.6em;height:2.6em}
.tdm-header-text{flex:1;min-width:0}
.tdm-title{margin:0;font-size:2.1em;font-weight:700;line-height:1.15}
.tdm-subtitle{margin:.3em 0 0;color:var(--muted);font-size:1.1em}
.tdm-badge{display:flex;align-items:center;gap:.6em;border:1.5px solid var(--amber);color:var(--amber);border-radius:999px;padding:.5em 1.1em;font-weight:600;white-space:nowrap}
.tdm-badge svg{width:1.8em;height:1.8em}
.tdm-grid{display:grid;grid-template-columns:1fr 1.1fr;gap:1.1em;flex:1;min-height:0}
.tdm-card{min-height:0;background:var(--card);border:1px solid var(--line);border-radius:1em;padding:1.3em}
.tdm-card-title{display:flex;align-items:center;gap:.7em;margin:0 0 1em;font-size:1.35em;font-weight:600}
.tdm-card-title svg{width:1.3em;height:1.3em;color:#aab6cf}
.tdm-label{display:block;font-size:1.2em;margin-bottom:.6em}
.tdm-row{display:flex;gap:.8em}
.tdm-number{flex:1;display:flex;align-items:center;border:1px solid var(--line);border-radius:.7em;background:#0f1626;padding:0 .5em 0 1em;min-width:0}
.tdm-days{flex:1;min-width:0;background:transparent;border:0;outline:0;color:var(--text);font-size:2em;font-weight:600;padding:.3em 0;-moz-appearance:textfield;font-family:inherit}
.tdm-days::-webkit-outer-spin-button,.tdm-days::-webkit-inner-spin-button{-webkit-appearance:none;margin:0}
.tdm-number:focus-within{border-color:var(--blue);box-shadow:0 0 0 2px rgba(59,130,246,.3)}
.tdm-number.tdm-invalid{border-color:var(--red)}
.tdm-spin{display:flex;flex-direction:column}
.tdm-spin button{background:transparent;border:0;color:var(--muted);cursor:pointer;padding:.1em .3em;line-height:0}
.tdm-spin button:hover{color:var(--text)}
.tdm-spin svg{width:1.3em;height:1.3em}
.tdm-unit{flex:1;display:flex;align-items:center;border:1px solid var(--line);border-radius:.7em;background:#0f1626;padding:0 1em;font-size:1.6em;color:var(--muted)}
.tdm-hint{display:flex;align-items:center;gap:.6em;color:var(--muted);margin:1em 0 0}
.tdm-hint svg{width:1.3em;height:1.3em}
.tdm-divider{height:1px;background:var(--line);margin:1.2em 0}
.tdm-switch-row{display:flex;align-items:center;gap:1em;font-size:1.2em;cursor:pointer}
.tdm-switch{position:relative;width:3.4em;height:2em;flex:none}
.tdm-switch input{position:absolute;inset:0;opacity:0;margin:0;cursor:pointer;z-index:1}
.tdm-slider{position:absolute;inset:0;border-radius:999px;background:#334058;transition:background .15s}
.tdm-slider::after{content:"";position:absolute;top:.2em;left:.2em;width:1.6em;height:1.6em;border-radius:50%;background:#fff;transition:transform .15s}
.tdm-switch input:checked+.tdm-slider{background:var(--blue)}
.tdm-switch input:checked+.tdm-slider::after{transform:translateX(1.4em)}
.tdm-switch input:focus-visible+.tdm-slider{outline:2px solid #fff;outline-offset:2px}
.tdm-status{display:flex;align-items:center;gap:1.6em;padding:.2em .4em 1.2em;border-bottom:1px solid var(--line)}
.tdm-status-icon{width:5.2em;height:5.2em;border-radius:50%;background:var(--green);color:#0b1b14;display:grid;place-items:center;flex:none}
.tdm-status-icon svg{width:3em;height:3em}
.tdm-ic-off{display:none}
.tdm-status-name{font-size:2.6em;font-weight:700;color:var(--green);line-height:1.1}
.tdm-status-line{font-size:1.2em;color:var(--muted);margin-top:.3em}
.tdm-status-line b{color:var(--text);font-weight:600}
.tdm-off .tdm-status-icon{background:#475569;color:#e2e8f0}
.tdm-off .tdm-ic-on{display:none}.tdm-off .tdm-ic-off{display:block}
.tdm-off .tdm-status-name{color:#94a3b8}
.tdm-card:has(.tdm-stats){display:flex;flex-direction:column}
.tdm-stats{display:grid;grid-template-columns:repeat(3,1fr);margin-top:auto;padding-top:1.1em}
.tdm-stat{padding:0 1em;border-left:1px solid var(--line);display:flex;flex-direction:column;gap:.35em;min-width:0}
.tdm-stat:first-child{border-left:0;padding-left:0}
.tdm-stat svg{width:1.8em;height:1.8em;color:#aab6cf}
.tdm-stat-label{color:var(--muted);font-size:1.05em}
.tdm-stat-value{font-size:1.7em;font-weight:700;overflow-wrap:anywhere}
.tdm-message{display:flex;align-items:flex-start;gap:.9em;padding:.9em 1.2em;font-size:1.1em;line-height:1.4;border-color:#2c4a82;background:rgba(59,130,246,.1)}
.tdm-message[hidden]{display:none}
.tdm-message svg{width:1.5em;height:1.5em;color:var(--blue);margin-top:.05em}
.tdm-message-text{white-space:pre-line;min-width:0;overflow-wrap:anywhere}
.tdm-message.tdm-warn{border-color:#8a6a10;background:rgba(245,179,1,.1)}
.tdm-message.tdm-warn svg{color:var(--amber)}
.tdm-footer{display:flex;align-items:stretch;gap:1.2em}
.tdm-warning{flex:1 1 0;min-width:0;display:flex;gap:1em;align-items:flex-start;border:1.5px solid #b4413c;background:rgba(239,68,68,.1);border-radius:.9em;padding:1em 1.2em;line-height:1.4}
.tdm-warning svg{width:2.4em;height:2.4em;color:var(--red)}
.tdm-warning-title{color:#f87171;font-weight:700;font-size:1.3em}
.tdm-actions{display:flex;flex-direction:column;justify-content:center;gap:.6em;align-items:flex-end}
.tdm-save{display:flex;align-items:center;gap:.7em;background:var(--blue);color:#fff;border:0;border-radius:.6em;padding:.9em 1.4em;font-size:1.15em;font-weight:600;cursor:pointer;font-family:inherit}
.tdm-save svg{width:1.4em;height:1.4em}
.tdm-save:hover{filter:brightness(1.1)}
.tdm-save:focus-visible{outline:2px solid #fff;outline-offset:2px}
.tdm-save:disabled{opacity:.45;cursor:not-allowed;filter:none}
.tdm-msg{min-height:1.3em;font-size:1em;color:var(--muted);text-align:right;max-width:22em}
.tdm-msg.ok{color:var(--green)}.tdm-msg.err{color:#f87171}
@container (max-width:620px){
  .tdm-body{font-size:min(2.6cqw,1.25cqh)}
  .tdm-grid{grid-template-columns:1fr}
  .tdm-header{flex-wrap:wrap}
  .tdm-stats{grid-template-columns:1fr 1fr 1fr}
  .tdm-footer{flex-direction:column}
  .tdm-actions{align-items:stretch}
  .tdm-msg{text-align:left;max-width:none}
}

descriptor.controllerScript:
/* Gestión de borrado de telemetría: lee y escribe atributos (retención en días y borrado automático) */
self.onInit = function () {
    var ctx = self.ctx;
    var root = ctx.$container[0];
    var q = function (s) { return root.querySelector(s); };

    self.el = {
        title: q('.tdm-title'), subtitle: q('.tdm-subtitle'), warning: q('.tdm-warning'),
        days: q('.tdm-days'), number: q('.tdm-number'), up: q('.tdm-up'), down: q('.tdm-down'),
        auto: q('.tdm-auto'), save: q('.tdm-save'), msg: q('.tdm-msg'), root: q('.tdm-root'),
        statusName: q('.tdm-status-name'), threshold: q('.tdm-threshold'), schedule: q('.tdm-schedule'),
        vKeep: q('.tdm-v-keep'), vDeleted: q('.tdm-v-deleted'), vUsage: q('.tdm-v-usage'),
        message: q('.tdm-message'), messageText: q('.tdm-message-text')
    };
    // Valores guardados (lo que hay en los atributos) y valores del formulario (lo que edita la persona)
    self.saved = { days: null, auto: null };
    self.form = { days: null, auto: false };
    self.dirty = false;
    self.saving = false;

    var s = ctx.settings || {};
    self.el.title.textContent = s.title || 'Gestión de borrado de telemetría';
    self.el.subtitle.textContent = s.subtitle || 'Configure un umbral de antigüedad para eliminar automáticamente los datos más antiguos.';
    self.el.schedule.textContent = s.scheduleText || 'Se ejecuta diario a las 00:00 horas';
    if (s.showWarning === false) { self.el.warning.style.display = 'none'; }

    // Mensaje opcional: solo se muestra si se configuró texto en los ajustes
    var msgText = (s.customMessage || '').trim();
    self.el.message.hidden = !msgText;
    self.el.messageText.textContent = msgText;
    self.el.message.classList.toggle('tdm-warn', s.messageType === 'warning');

    self.el.days.addEventListener('input', function () {
        self.form.days = self.el.days.value === '' ? null : Number(self.el.days.value);
        self.dirty = true;
        self.render();
    });
    self.el.up.addEventListener('click', function () { self.step(1); });
    self.el.down.addEventListener('click', function () { self.step(-1); });
    self.el.auto.addEventListener('change', function () {
        self.form.auto = self.el.auto.checked;
        self.dirty = true;
        self.render();
    });
    self.el.save.addEventListener('click', function () { self.save(); });

    self.render();
};

self.step = function (delta) {
    var cur = Number(self.form.days);
    if (isNaN(cur)) { cur = 0; }
    self.form.days = Math.max(1, Math.round(cur) + delta);
    self.dirty = true;
    self.render();
};

/* Busca el último valor de un dato por etiqueta o nombre de clave */
self.find = function (name) {
    if (!name) { return { found: false }; }
    var data = self.ctx.data || [];
    for (var i = 0; i < data.length; i++) {
        var dk = data[i].dataKey;
        if (dk && (dk.label === name || dk.name === name)) {
            var arr = data[i].data;
            var v = (arr && arr.length) ? arr[arr.length - 1][1] : null;
            return { found: true, value: v, attrName: dk.name };
        }
    }
    return { found: false };
};

self.toNum = function (v) {
    if (v === null || v === undefined || v === '') { return null; }
    var n = parseFloat(v);
    return isNaN(n) ? null : n;
};
self.toBool = function (v) {
    return v === true || v === 1 || v === '1' || String(v).toLowerCase() === 'true';
};
self.fmt = function (v, unit) {
    if (v === null || v === undefined || v === '') { return '—'; }
    var n = self.toNum(v);
    var dec = self.ctx.settings && self.ctx.settings.decimals;
    dec = (dec === undefined || dec === null) ? 1 : dec;
    var out = (n === null) ? String(v) : n.toLocaleString('es-PE', { maximumFractionDigits: dec });
    return unit ? out + ' ' + unit : out;
};

self.onDataUpdated = function () {
    var s = self.ctx.settings || {};
    var r = self.find(s.retentionKey);
    var a = self.find(s.autoDeleteKey);
    self.saved.days = r.found ? self.toNum(r.value) : null;
    self.saved.auto = a.found ? self.toBool(a.value) : null;
    if (!self.dirty) {
        self.form.days = self.saved.days;
        self.form.auto = self.saved.auto === true;
    }
    self.render();
};

self.onResize = function () {};
self.onDestroy = function () {};

self.validate = function () {
    var s = self.ctx.settings || {};
    var min = s.minDays || 1, max = s.maxDays || 3650;
    var d = self.form.days;
    if (d === null || isNaN(d) || Math.floor(d) !== d) { return 'Ingrese un número entero de días.'; }
    if (d < min) { return 'El mínimo es ' + min + ' día(s).'; }
    if (d > max) { return 'El máximo es ' + max + ' días.'; }
    return null;
};

self.render = function () {
    var s = self.ctx.settings || {};
    var e = self.el;
    var f = self.form;

    if (document.activeElement !== e.days) { e.days.value = (f.days === null || isNaN(f.days)) ? '' : f.days; }
    e.auto.checked = !!f.auto;

    var err = self.dirty ? self.validate() : null;
    e.number.classList.toggle('tdm-invalid', !!err);
    e.save.disabled = self.saving || !self.dirty || !!err;
    if (!self.saving) { self.setMsg(err || (self.dirty ? 'Hay cambios sin guardar.' : ''), err ? 'err' : ''); }

    // Estado actual: derivado del atributo guardado de borrado automático
    var active = self.saved.auto === true;
    e.root.classList.toggle('tdm-off', !active);
    e.statusName.textContent = active ? 'Activo' : 'Inactivo';
    e.schedule.textContent = active ? (s.scheduleText || 'Se ejecuta diario a las 00:00 horas') : 'El borrado automático está deshabilitado';

    var daysTxt = (self.saved.days === null) ? '—' : self.saved.days + ' días';
    e.threshold.textContent = daysTxt;
    e.vKeep.textContent = (self.saved.days === null) ? '—' : self.saved.days + ' días+';

    var del = self.find(s.deletedKey), use = self.find(s.usageKey);
    e.vDeleted.textContent = self.fmt(del.found ? del.value : null, s.deletedUnit);
    e.vUsage.textContent = self.fmt(use.found ? use.value : null, s.usageUnit);
};

self.setMsg = function (text, cls) {
    self.el.msg.textContent = text || '';
    self.el.msg.className = 'tdm-msg' + (cls ? ' ' + cls : '');
};

self.save = function () {
    var ctx = self.ctx, s = ctx.settings || {};
    var err = self.validate();
    if (err) { self.setMsg(err, 'err'); return; }

    var ds = ctx.datasources && ctx.datasources[0];
    if (!ds || !ds.entityId || !ds.entityType) {
        self.setMsg('No hay una entidad configurada en la fuente de datos.', 'err');
        return;
    }
    var retName = self.find(s.retentionKey).attrName || s.retentionKey;
    var autoName = self.find(s.autoDeleteKey).attrName || s.autoDeleteKey;
    var attrs = [];
    if (retName) { attrs.push({ key: retName, value: self.form.days }); }
    if (autoName) { attrs.push({ key: autoName, value: !!self.form.auto }); }
    if (!attrs.length) {
        self.setMsg('Configure los datos "Mantener datos" y "Borrado automático" en los ajustes del widget.', 'err');
        return;
    }

    self.saving = true;
    self.el.save.disabled = true;
    self.setMsg('Guardando…', '');
    var entityId = { entityType: ds.entityType, id: ds.entityId };
    ctx.attributeService.saveEntityAttributes(entityId, s.attributeScope || 'SERVER_SCOPE', attrs).subscribe(
        function () {
            self.saving = false;
            self.saved.days = self.form.days;
            self.saved.auto = !!self.form.auto;
            self.dirty = false;
            self.render();
            self.setMsg('Configuración guardada.', 'ok');
            ctx.detectChanges && ctx.detectChanges();
        },
        function () {
            self.saving = false;
            self.render();
            self.setMsg('No se pudo guardar. Verifique sus permisos e intente de nuevo.', 'err');
        }
    );
};

self.typeParameters = function () {
    return { maxDatasources: 1, dataKeysOptional: false };
};
